//! A world generation's interface to the simulation ([`WorldgenCode`]):
//! what generates a superchunk's cells, and what lives on one, put
//! there on its turn the first tick it is hot -- queued as any rule
//! queues, under compares. It is the library of the type hooked into
//! generating the world. The numbers it generates by are the world's,
//! each by name: whoever runs the world hands them on, and knows
//! nothing of them.

use crate::SimulationTickState;
use chunk_storage::SuperchunkCells;
use coordinates::SuperchunkIndex;

/// The numbers a world is generated by, each with its name: as its file
/// keeps them, and as a window's sliders give them.
pub type GenerationNumbers = [(String, u64)];

/// What generates a world, as the library of the type hooked into
/// generating it.
#[derive(Clone, Copy, Debug)]
pub struct WorldgenCode {
    /// The cells of a superchunk of the world of a seed, as the numbers
    /// say: the same whenever it is made.
    pub generate_cells: fn(&GenerationNumbers, u64, SuperchunkIndex) -> SuperchunkCells,
    /// Queues on a superchunk's turn what lives on it, the first tick it
    /// is hot, as the numbers say, for the world of a seed.
    pub populate: fn(&mut SimulationTickState, &GenerationNumbers, u64),
}
